ROOT = Path(__file__).parent
doc = Document()
sec = doc.sections[0]
sec.page_width, sec.page_height = Cm(21), Cm(29.7)
sec.top_margin, sec.bottom_margin = Cm(1.7), Cm(1.7)
sec.left_margin = sec.right_margin = Cm(1.6)
normal = doc.styles['Normal']
normal.font.name = 'DejaVu Sans'
normal.font.size = Pt(10)
normal.paragraph_format.space_after = Pt(7)
normal.paragraph_format.line_spacing = 1.12
for name, size in [('Title', 25), ('Heading 1', 18), ('Heading 2', 12), ('Subtitle', 12)]:
    s = doc.styles[name]
    s.font.name = 'DejaVu Sans'
    s.font.size = Pt(size)
    s.font.color.rgb = RGBColor(0, 0, 0)
for style in doc.styles:
    for border in list(style.element.iter(qn('w:pBdr'))):
        border.getparent().remove(border)
doc.styles['Caption'].font.size = Pt(8)
doc.styles['Caption'].font.color.rgb = RGBColor(70, 70, 70)
sec.header.paragraphs[0].text = 'Platform Installer UI  •  Руководство пользователя'
sec.header.paragraphs[0].style = doc.styles['Caption']
f = sec.footer.paragraphs[0]
f.alignment = 2
f.add_run('26 октября 2026  •  ')
field = OxmlElement('w:fldSimple'); field.set(qn('w:instr'), 'PAGE'); f._p.append(field)
doc.core_properties.title = 'Platform Installer UI Руководство пользователя'
doc.core_properties.subject = 'Работа с проектом, серверами, службами, приложениями и установкой'

def p(text): doc.add_paragraph(text)
def h(text): doc.add_heading(text, 2)
def steps(items):
    for n, text in enumerate(items, 1): p(f'{n}. {text}')
figure_number = 0
def pic(name, caption):
    global figure_number
    figure_number += 1
    caption = re.sub(r'^Рисунок \d+\.', f'Рисунок {figure_number}.', caption)
    para = doc.add_paragraph()
    para.paragraph_format.keep_with_next = True
    para.add_run().add_picture(str(ROOT / 'images' / name), width=Cm(17.8))
    doc.add_paragraph(caption, 'Caption')
def page(title):
    doc.add_page_break(); doc.add_heading(title, 1)

doc.add_heading('Platform Installer UI', 0)
doc.add_paragraph('Руководство пользователя', 'Subtitle')
p('Настольный интерфейс настройки и установки платформы')
p('Редакция от 26 октября 2026 года')
p('Руководство поможет открыть проект, описать серверы и размещение служб, настроить библиотеки приложений, сохранить конфигурацию и пройти путь от плана до результата установки.')
pic('01-start.png', 'Рисунок 1. Стартовый экран текущего приложения без открытого проекта.')
